# name: participant_side_bias_spread
# description: SD across participants of each person's proportion of Left choices; observed > null means the model (which has no side/response bias) under-produces person-level left/right response biases.
def test_statistic(df):
    return float(df.groupby("participant_id")["chose_left"].mean().std())

# name: more_switch_choice_short_minus_long
# description: Proportion choosing the sequence with more switches at lengths <= 3 minus the same at length 8 (trials with unequal switch counts); observed != null means the model's length scaling misstates how switch preference changes with sequence length (positive: stronger alternation preference in short sequences).
def _sw(s):
    return sum(1 for x, y in zip(s, s[1:]) if x != y)
def test_statistic(df):
    a, b = df["sequence_a"], df["sequence_b"]
    u = pd.unique(pd.concat([a, b])); sw = {s: _sw(s) for s in u}
    ka = a.map(sw).to_numpy(); kb = b.map(sw).to_numpy()
    n = a.str.len().to_numpy(); y = df["chose_left"].to_numpy()
    more = np.where(ka > kb, y, 1 - y).astype(float)
    d = ka != kb
    s = d & (n <= 3); l = d & (n == 8)
    if s.sum() == 0 or l.sum() == 0:
        return 0.0
    return float(more[s].mean() - more[l].mean())

# name: longest_run_avoidance_equal_switches
# description: Among trials whose two sequences have the same number of switches but different longest runs, the proportion choosing the sequence with the shorter longest run; observed > null means the model under-weights streak (long-run) avoidance beyond switch count.
import re
def _maxrun(s):
    return max(len(m.group(0)) for m in re.finditer(r"H+|T+", s))
def _sw(s):
    return sum(1 for x, y in zip(s, s[1:]) if x != y)
def test_statistic(df):
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    mr = {s: _maxrun(s) for s in u}; sw = {s: _sw(s) for s in u}
    ra = df["sequence_a"].map(mr).to_numpy(); rb = df["sequence_b"].map(mr).to_numpy()
    ka = df["sequence_a"].map(sw).to_numpy(); kb = df["sequence_b"].map(sw).to_numpy()
    m = (ka == kb) & (ra != rb)
    if m.sum() == 0:
        return 0.5
    y = df["chose_left"].to_numpy()[m]
    chose_shorter = np.where(ra[m] < rb[m], y, 1 - y)
    return float(chose_shorter.mean())

# name: balance_preference_equal_switches
# description: Among trials whose sequences have equal switch counts but different |#H - #T|, the proportion choosing the more H/T-balanced sequence; observed > null means the model under-produces preference for balanced head/tail counts.
def _sw(s):
    return sum(1 for x, y in zip(s, s[1:]) if x != y)
def test_statistic(df):
    a, b = df["sequence_a"], df["sequence_b"]
    n = a.str.len().to_numpy()
    ia = np.abs(2 * a.str.count("H").to_numpy() - n); ib = np.abs(2 * b.str.count("H").to_numpy() - n)
    u = pd.unique(pd.concat([a, b])); sw = {s: _sw(s) for s in u}
    ka = a.map(sw).to_numpy(); kb = b.map(sw).to_numpy()
    m = (ka == kb) & (ia != ib)
    if m.sum() == 0:
        return 0.5
    y = df["chose_left"].to_numpy()[m]
    return float(np.where(ia[m] < ib[m], y, 1 - y).mean())

# name: switch_preference_person_bimodality
# description: Across participants, the fraction whose rate of choosing the more-switching sequence (unequal-switch trials) is below 0.4 (streak-preferers); observed > null means the model's normal population of switch beliefs under-produces a distinct subgroup preferring fewer switches.
def _sw(s):
    return sum(1 for x, y in zip(s, s[1:]) if x != y)
def test_statistic(df):
    a, b = df["sequence_a"], df["sequence_b"]
    u = pd.unique(pd.concat([a, b])); sw = {s: _sw(s) for s in u}
    ka = a.map(sw).to_numpy(); kb = b.map(sw).to_numpy()
    y = df["chose_left"].to_numpy()
    d = ka != kb
    more = pd.Series(np.where(ka > kb, y, 1 - y)[d].astype(float))
    r = more.groupby(df["participant_id"].to_numpy()[d]).mean()
    return float((r < 0.4).mean())
